import sys
from math import comb

def solve():
    data = sys.stdin.read().split()
    N, P = int(data[0]), int(data[1])
    half = N // 2
    a = b = half

    num_partitions = comb(N - 1, half - 1)
    max_edges_bip = a * b

    c = {}

    for sA in range(1, a + 1):
        for sB in range(0, b + 1):
            max_e = sA * sB
            arr = [comb(max_e, m) for m in range(max_e + 1)]
            for tA in range(1, sA + 1):
                for tB in range(0, sB + 1):
                    if tA == sA and tB == sB:
                        continue
                    if (tA, tB) not in c:
                        continue
                    coeff = comb(sA - 1, tA - 1) * comb(sB, tB)
                    if coeff == 0:
                        continue
                    c_arr = c[(tA, tB)]
                    rA = sA - tA
                    rB = sB - tB
                    max_e2 = rA * rB
                    for m1 in range(len(c_arr)):
                        if c_arr[m1] == 0:
                            continue
                        for m2 in range(max_e2 + 1):
                            if m1 + m2 <= max_e:
                                arr[m1 + m2] -= coeff * c_arr[m1] * comb(max_e2, m2)
            c[(sA, sB)] = arr

    connected = c.get((a, b), [0] * (max_edges_bip + 1))
    while len(connected) <= max_edges_bip:
        connected.append(0)

    results = []
    for M in range(N - 1, N * (N - 1) // 2 + 1):
        if M <= max_edges_bip:
            ans = (num_partitions * connected[M]) % P
        else:
            ans = 0
        results.append(str(ans))

    print(' '.join(results))

solve()
